css='''<style id="objective-details-css">.detail-button,.journey button,#objective-view button{background:#08283e;color:#eef7ff;border:1px solid #4de3ff99;border-radius:9px;padding:10px 13px;font:600 .85rem system-ui;cursor:pointer}.detail-button:hover,.journey button:hover,#objective-view button:hover{background:#155272}.objective-launch{display:flex;flex-wrap:wrap;gap:8px;margin-top:14px}.journey{background:#06111cf2;border:1px solid #4de3ff88;border-radius:18px;padding:22px}.journey h3{margin:0;font-size:1.3rem}.journey-controls{display:flex;gap:7px;flex-wrap:wrap;margin:14px 0}.journey-path{display:flex;gap:7px;margin:16px 0}.journey-path button{flex:1;font-size:.73rem;padding:10px 3px}.journey-path button.selected{background:#165d58;border-color:#55e6a5;box-shadow:0 0 16px #55e6a544}.journey-path button.blocked{opacity:.45}#flow-detail{min-height:190px;border-left:3px solid #55e6a5;padding-left:15px}#flow-detail h4{margin:0 0 10px;color:#f6d060;font-size:1.15rem}#flow-detail p{font-size:1rem}#flow-detail .reading{font-size:1.15rem;font-weight:750;color:#55e6a5}.slide .flow-evidence{font-size:.8rem}#objective-view{width:min(1200px,94vw);height:92vh;max-height:94vh;background:#071522;color:#edf7ff;border:1px solid #4de3ff;border-radius:20px;padding:26px;overflow:auto}#objective-view::backdrop{background:#000d}#objective-view header{display:flex;justify-content:space-between;gap:16px;align-items:center}#objective-view nav{display:flex;gap:8px;margin:12px 0 20px}#objective-view h2{font-size:1.75rem;margin:.5em 0}#objective-view p,#objective-view li{font:1.05rem/1.55 system-ui}#objective-view li{padding-bottom:12px}#objective-view .detail-grid{display:grid;grid-template-columns:1.1fr 1fr;gap:28px}#objective-view .number-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}#objective-view .number-card{padding:16px;background:#102e40;border-radius:12px;border:1px solid #4de3ff44}#objective-view .number-card strong{display:block;font-size:1.5rem;color:#55e6a5;margin-bottom:8px}#objective-view .number-card span{font-size:.95rem;line-height:1.45}#objective-view .limit{padding:16px;border-left:3px solid #f6d060;background:#ffffff08}#objective-view .status{color:#55e6a5;font-weight:bold}#objective-view .source{font-size:.85rem;color:#bacbd8}@media(max-width:760px){#objective-view .detail-grid{grid-template-columns:1fr}.journey{padding:14px}#objective-view nav{flex-wrap:wrap}}@media(max-height:800px){.journey{padding:15px}.journey h3{font-size:1.1rem}#flow-detail{min-height:170px}#flow-detail p{font-size:.9rem}.journey-controls{margin:9px 0}.journey-path{margin:10px 0}.detail-button{padding:8px 10px}.slide.s7 p{font-size:1rem}.slide.s7 h2{font-size:2.2rem}}</style>'''
