script='''<dialog id="objective-view"><header><span>Objective → method → evidence → interpretation</span><button onclick="document.getElementById('objective-view').close()">Close ×</button></header><nav>'''+''.join(f'<button onclick="showObjective({i})">{i+1}. {label}</button>' for i,label in enumerate(['Design','Develop','Test','Evaluate']))+'''</nav><div id="objective-content"></div></dialog><script>
const objectiveEvidence=REPLACE_DATA;
function showObjective(i){const d=objectiveEvidence[i],v=document.getElementById('objective-view');document.getElementById('objective-content').innerHTML=`<h2>${d.title}</h2><p class="status">${d.status}</p><p><b>What we set out to do:</b> ${d.goal}</p><div class="detail-grid"><div><h3>How it was implemented</h3><ol>${d.steps.map(x=>`<li>${x}</li>`).join('')}</ol></div><div><h3>Recorded evidence</h3><div class="number-grid">${d.numbers.map(x=>`<div class="number-card"><strong>${x[0]}</strong><span>${x[1]}</span></div>`).join('')}</div><p><b>What the numbers mean:</b> ${d.meaning}</p></div></div><p class="limit"><b>What remains unproven:</b> ${d.limits}</p><p class="source">Source: ${d.source}. These are report results, not a new test run.</p>`;if(!v.open)v.showModal();v.scrollTop=0}
document.getElementById('objective-view').addEventListener('keydown',e=>e.stopPropagation());
let flowIndex=0,flowOffline=false;
const flowSteps=[['1 · Measure the signals','36.7 °C · SpO₂ 98% · HR 142 bpm','Illustrative valid reading only. MAX30102 supplies optical pulse/oxygen signals; MLX90614 estimates surface temperature. Sensor validity must be checked before a value is used.'],['2 · ESP32 validates and responds','Validate → timestamp → local rules → SD','ESP32 associates the sample with its session and time, checks validity and thresholds, updates the display and triggers local indicators when required. It stores records for synchronisation. AI is not in this local alert path.'],['3 · Backend receives and stores','JSON request → Flask → PostgreSQL','The authenticated API validates and stores the reading. The backend can use the preceding 120 seconds to form 12 AI features. One sample alone does not establish a trend or a trustworthy AI risk estimate.'],['4 · Frontend presents the record','36.7 °C · 98% · 142 bpm + timestamp','React reads backend records and displays current values, histories, connectivity and alerts. This illustrative display repeats the same sample so the audience can follow it; no screen-latency measurement is implied.'],['5 · Nurse reviews and responds','Review → assess the patient → decide','The nurse checks the timestamp, signal quality, trends and alerts, then assesses the patient and follows the applicable care protocol. The project supports attention; it has not measured improved clinical outcomes.']];
function flowSelect(i){flowIndex=i;drawFlow()}function flowNext(){flowIndex=(flowIndex+1)%5;drawFlow()}function flowMode(v){flowOffline=v;drawFlow()}
function drawFlow(){let [h,n,t]=flowSteps[flowIndex];if(flowOffline&&flowIndex===1){n='Local monitoring continues · queue on microSD';t='The ESP32 retains records and continues local display/threshold alerts. After connectivity returns, queued records can be synchronised. The report did not establish a quantified outage-duration or delivery guarantee.'}if(flowOffline&&flowIndex>=2){h=flowIndex===2?'3 · Network unavailable':flowIndex===3?'4 · No fresh remote sample':'5 · Use bedside assessment';n='Latest illustrative reading is not delivered remotely';t=flowIndex===2?'The new sample stays on the device. Flask/PostgreSQL cannot receive it until a connection is restored.':flowIndex===3?'The dashboard has no newly synchronised record. Previous data must be interpreted with its timestamp/connectivity status; it must not be treated as fresh.':'The nurse relies on bedside observations and local device indicators. A disconnected dashboard cannot provide a current remote reading.'}document.getElementById('flow-detail').innerHTML=`<h4>${h}</h4><p class="reading">${n}</p><p>${t}</p>`;document.querySelectorAll('[data-stage]').forEach((b,i)=>{b.classList.toggle('selected',i===flowIndex);b.classList.toggle('blocked',flowOffline&&i>=2);b.setAttribute('aria-pressed',i===flowIndex)});document.querySelectorAll('.journey-controls button').forEach((b,i)=>{if(i<2)b.setAttribute('aria-pressed',(i===1)===flowOffline)})}drawFlow();
</script>'''.replace('REPLACE_DATA',json.dumps(D,ensure_ascii=False))
